--  DDL for Trigger FM_SUPPLIER_MASTER_TR
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE TRIGGER "FAKHRUDDINERP"."FM_SUPPLIER_MASTER_TR" 
BEFORE INSERT ON FM_SUPPLIER_MASTER FOR EACH ROW 
BEGIN
  
  IF INSERTING THEN 
  
      IF :NEW.ORG_ID=21 THEN 
          DELETED_BY, IS_DELETED, IS_UPDATED, CREATED_AT, UPDATED_AT, DELETED_AT, BRANCH_ID, CONTROL_ACCOUNT_ID, CUST_TYPE)
           VALUES (:NEW.ID,1
           , :NEW.ORG_ID, :NEW.COMP_ID, :NEW.CREATED_BY, :NEW.UPDATED_BY, 
             :NEW.DELETED_BY, :NEW.IS_DELETED, :NEW.IS_UPDATED, :NEW.CREATED_AT, :NEW.UPDATED_AT, :NEW.DELETED_AT, :NEW.BRANCH_ID, 1112, 'SUPPLIER'
           ) ;

      END IF;
  END IF;
  
END;
